scripts.factorial_mod:
def solve(inputs: dict) -> float:
    N = inputs['N']
    MOD = inputs['MOD']

    # Compute N! mod MOD
    result = 1
    for i in range(1, N + 1):
        result = (result * i) % MOD

    return float(result)

scripts.divide_and_sum:
def solve(inputs: dict) -> float:
    A = inputs['A']
    B = inputs['B']

    # Divide each A_i by B_i and keep only the integer part, then sum
    total = sum(int(a // b) for a, b in zip(A, B))

    return float(total)

scripts.gcd_all:
import math

def solve(inputs: dict) -> float:
    values = inputs['VALUES']

    # Compute GCD of all values
    result = values[0]
    for val in values[1:]:
        result = math.gcd(result, val)

    return float(result)

scripts.lcg_iteration:
def solve(inputs: dict) -> float:
    s = inputs['SEED']
    A = inputs['A']
    B = inputs['B']
    M = inputs['M']
    K = inputs['K']

    # Repeat K times: s = (A * s + B) % M
    for _ in range(K):
        s = (A * s + B) % M

    return float(s)

scripts.continued_fraction_numerator:
def solve(inputs: dict) -> float:
    terms = inputs['TERMS']

    # Compute continued fraction numerators
    # p_{-1} = 1, p_0 = a_0
    # p_n = a_n * p_{n-1} + p_{n-2}

    if len(terms) == 0:
        return 0.0

    p_prev = 1  # p_{-1}
    p = terms[0]  # p_0

    # Apply the recurrence for remaining terms
    for i in range(1, len(terms)):
        p_new = terms[i] * p + p_prev
        p_prev = p
        p = p_new

    return float(p)

